            const d = await sendChatRequest(api, prompt, extra);
            return String((d && d.choices && d.choices[0] && d.choices[0].message && d.choices[0].message.content) || '').replace(/<think>[\s\S]*?<\/think>/g, '').trim() || null;
        } catch (e) { return null; }
    };
